            subtract(tmp1, 0, x, xOffset, tmp2, 0);     
            divide(y, yOffset, tmp2, 0, tmp1, 0);       
            atan(tmp1, 0, tmp2, 0);                     
            result[resultOffset] =
                    ((tmp2[0] <= 0) ? -FastMath.PI : FastMath.PI) - 2 * tmp2[0]; 
            for (int i = 1; i < tmp2.length; ++i) {
                result[resultOffset + i] = -2 * tmp2[i]; 
            }

        }



