          double ratio = ya * denomr;
          double temp = ratio * 1073741824.0;
          double ra = ratio + temp - temp;
          double rb = ratio - ra;

          temp = denom * 1073741824.0;
          double za = denom + temp - temp;
          double zb = denom - za;

